/* === Parent card === */
.stack-card {
  /* base sizing */
  --w: 250px;
  --h: 300px;

  /* how much each layer shrinks */
  --step: 20px;

  /* initial offset per layer */
  --offset: 10px;

  /* hover multiplies the offset (was 2x in your code) */
  --hover-mult: 2;

  /* active offset (your code effectively becomes +~40px per layer after press) */
  --active-mult: 6;

  position: relative;
  width: var(--w);
  height: var(--h);
  border-radius: 1rem;

  font-family: Montserrat, sans-serif;
  font-size: large;

  background: rgba(50, 50, 50, 0.6);

  transform: rotateX(-15deg) rotateY(-35deg);
  perspective: 600px;

  box-shadow:
    rgba(0, 0, 0, 0.2) 4px -4px 18px,
    0rem 5rem 25px 10px rgba(0, 0, 0, 0.25);

  border: dashed 2px rgba(100, 100, 100, 0.4);
  transition: 0.6s ease-in-out;
  user-select: none;
}

.stack-card:hover {
  transform: translateY(-15px) translateX(15px) rotateX(-15deg) rotateY(-35deg);
  background: rgba(70, 70, 70, 0.6);
  border: dashed 2px rgba(150, 150, 150, 0.3);
  box-shadow:
    rgba(0, 0, 0, 0.2) 4px -4px 18px,
    -1rem 5rem 25px 20px rgba(0, 0, 0, 0.2);
}

.stack-card:active {
  cursor: none;
  height: 250px;
  transition: 0.6s ease-in-out;
  transition-delay: 0.1s;
  box-shadow:
    rgba(0, 0, 0, 0.3) 4px -4px 18px,
    -1rem 7rem 25px 40px rgba(0, 0, 0, 0.2);
  border: dashed 2px rgba(120, 120, 120, 0.5);
}

/* === Layers (generated via --i) === */
.layer {
  /* computed sizes */
  width: calc(var(--w) - (var(--i) * var(--step)));
  height: calc(var(--h) - (var(--i) * var(--step)));

  /* computed base offset */
  transform: translateY(calc(var(--i) * var(--offset)))
    translateX(calc(var(--i) * var(--offset) * -1));

  position: absolute;
  top: 0;
  left: 0;
  border-radius: 1rem;

  box-shadow: rgba(0, 0, 0, 0.3) 4px -4px 12px;
  border: solid 1px rgba(120, 120, 120, 0.4);

  /* computed background: matches your gradual fade */
  background: rgba(30, 30, 30, calc(0.7 - (var(--i) * 0.05)));

  transition: 0.4s cubic-bezier(0.87, 0, 0.13, 1);
  transition-delay: 0.05s;
}

/* Slight background change on hover (same idea as your per-layer rules) */
.stack-card:hover .layer {
  background: rgba(30, 30, 30, calc(0.65 - (var(--i) * 0.05)));
}

/* Hover spread (your code doubles the offsets) */
.stack-card:hover .layer {
  transform: translateY(calc(var(--i) * var(--offset) * var(--hover-mult)))
    translateX(calc(var(--i) * var(--offset) * var(--hover-mult) * -1));
}

/* Active spread (your pressed state pushes layers much further) */
.stack-card:active .layer {
  transform: translateY(calc(var(--i) * var(--offset) * var(--active-mult)))
    translateX(calc(var(--i) * var(--offset) * var(--active-mult) * -1));
}

/* Your special case: layer 1 active was a small inverse nudge */
.stack-card:active .layer[style*="--i: 0"] {
  transform: translateY(10px) translateX(-10px);
}

/* === Label via pseudo-element (replaces nested .label div) === */
.layer::after {
  content: var(--label);
  position: absolute;
  left: calc(100% + 8px);
  top: 50%;
  transform: translateY(-50%) scale(1);
  transform-origin: left center;

  color: #ccc;
  font-size: 0.9rem;
  font-weight: 300;
  text-shadow: none;

  opacity: 0;
  pointer-events: none;

  transition:
    color 0.3s,
    text-shadow 0.3s,
    transform 0.3s,
    opacity 0.3s;
}

.layer:hover::after {
  opacity: 1;
  color: #fff;
  text-shadow: 0 0 5px #fff;
  transform: translateY(-50%) scale(1.3);
}
